<?php require __DIR__.'/../app/bootstrap.php'; require __DIR__.'/../app/layout.php'; require_permission('manage_purchases');
$products=db()->query('SELECT id,sku,product_barcode,product_name,color,size,serial_tracking FROM products WHERE active=1 ORDER BY product_name')->fetchAll();$suppliers=db()->query('SELECT id,party_code,party_name FROM suppliers WHERE active=1 ORDER BY party_name')->fetchAll();$locations=db()->query('SELECT id,code,name FROM locations WHERE active=1 ORDER BY code')->fetchAll();$err='';$success='';$labelBatches=[];
if($_SERVER['REQUEST_METHOD']==='POST'){csrf_check();if(!form_once_claim('purchase_new'))$err='This purchase form was already submitted. Check Purchase History before posting again.';$supplierId=(int)($_POST['supplier_id']??0);$invoice=trim($_POST['invoice_no']??'');$date=$_POST['invoice_date']??date('Y-m-d');$pids=$_POST['product_id']??[];$batchNos=$_POST['batch_no']??[];$locIds=$_POST['location_id']??[];$qtys=$_POST['quantity']??[];$costs=$_POST['cost_price']??[];$costCodes=$_POST['cost_code']??[];$lines=[];$total=0;
 if(!$err)foreach($pids as $i=>$pid){$pid=(int)$pid;if($pid<=0)continue;$batch=trim($batchNos[$i]??'');$loc=(int)($locIds[$i]??0);$qty=(float)($qtys[$i]??0);$cost=(float)($costs[$i]??0);if($batch===''||$loc<=0||$qty<=0||$cost<0){$err='Every entered line needs product, batch, location, positive quantity and cost.';break;}$manualCostCode=trim($costCodes[$i]??'');$lines[]=['product_id'=>$pid,'batch'=>$batch,'location'=>$loc,'qty'=>$qty,'cost'=>$cost,'cost_code'=>$manualCostCode];$total+=$qty*$cost;}
 if(!$err&&!$supplierId)$err='Supplier is required.';if(!$err&&!$lines)$err='Add at least one purchase item.';
 if(!$err)try{db()->beginTransaction();$chk=db()->prepare('SELECT 1 FROM suppliers WHERE id=? AND active=1 FOR UPDATE');$chk->execute([$supplierId]);if(!$chk->fetchColumn())throw new Exception('Supplier is missing or inactive.');if($invoice!==''){$chk=db()->prepare('SELECT purchase_no FROM purchases WHERE supplier_id=? AND invoice_no=? LIMIT 1');$chk->execute([$supplierId,$invoice]);$dupNo=$chk->fetchColumn();if($dupNo)throw new Exception('Supplier invoice '.$invoice.' is already posted as '.$dupNo.'. Stock was not added again.');}foreach($lines as $ln){$chk=db()->prepare('SELECT 1 FROM locations WHERE id=? AND active=1');$chk->execute([$ln['location']]);if(!$chk->fetchColumn())throw new Exception('A selected stock location is missing or inactive.');}$purchaseNo='PUR-'.date('YmdHis').'-'.random_int(100,999);$st=db()->prepare('INSERT INTO purchases(purchase_no,supplier_id,invoice_no,invoice_date,total_cost,created_by) VALUES(?,?,?,?,?,?)');$st->execute([$purchaseNo,$supplierId,$invoice,$date,$total,current_user()['id']]);$purchaseId=(int)db()->lastInsertId();$firstBatchId=0;db()->prepare("INSERT INTO supplier_ledger(supplier_id,txn_type,credit,reference_type,reference_id,remarks,created_by) VALUES(?,'PURCHASE',?,'PURCHASE',?,?,?)")->execute([$supplierId,$total,$purchaseId,$purchaseNo,current_user()['id']]);
  foreach($lines as $ln){$st=db()->prepare('SELECT sku,serial_tracking FROM products WHERE id=? AND active=1 FOR UPDATE');$st->execute([$ln['product_id']]);$p=$st->fetch();if(!$p)throw new Exception('Product missing/inactive.');if((int)$p['serial_tracking']===1 && abs($ln['qty']-round($ln['qty']))>0.0001)throw new Exception('Serialized garments require whole-piece quantity.');
   $batchBarcode='PFB-'.preg_replace('/[^A-Z0-9]/i','',strtoupper($p['sku'])).'-'.date('ymd').'-'.strtoupper(bin2hex(random_bytes(3)));$batchCostCode=$ln['cost_code']!==''?$ln['cost_code']:'BC-'.strtoupper(bin2hex(random_bytes(4)));$st=db()->prepare('INSERT INTO batches(batch_no,batch_barcode,product_id,supplier_id,purchase_id,purchase_invoice_no,purchased_at,cost_price,cost_code,qty_received,qty_available) VALUES(?,?,?,?,?,?,?,?,?,?,?)');$st->execute([$ln['batch'],$batchBarcode,$ln['product_id'],$supplierId,$purchaseId,$invoice,$date,$ln['cost'],$batchCostCode,$ln['qty'],$ln['qty']]);$batchId=(int)db()->lastInsertId();if(!$firstBatchId)$firstBatchId=$batchId;$labelBatches[]=['id'=>$batchId,'label'=>$p['sku'].' · '.$ln['batch']];
   db()->prepare('INSERT INTO purchase_items(purchase_id,product_id,batch_id,location_id,quantity,cost_price) VALUES(?,?,?,?,?,?)')->execute([$purchaseId,$ln['product_id'],$batchId,$ln['location'],$ln['qty'],$ln['cost']]);db()->prepare('INSERT INTO inventory_balances(product_id,batch_id,location_id,qty) VALUES(?,?,?,?) ON DUPLICATE KEY UPDATE qty=qty+VALUES(qty)')->execute([$ln['product_id'],$batchId,$ln['location'],$ln['qty']]);db()->prepare("INSERT INTO stock_ledger(txn_type,product_id,batch_id,location_id,qty_in,reference_type,reference_id,unit_rate,remarks,created_by) VALUES('PURCHASE',?,?,?,?, 'PURCHASE',?,?,?,?)")->execute([$ln['product_id'],$batchId,$ln['location'],$ln['qty'],$purchaseId,$ln['cost'],$invoice,current_user()['id']]);db()->prepare('UPDATE products SET purchase_cost=? WHERE id=?')->execute([$ln['cost'],$ln['product_id']]);
   if((int)$p['serial_tracking']===1){$ins=db()->prepare("INSERT INTO product_serials(serial_barcode,product_id,batch_id,location_id,status) VALUES(?,?,?,?,'AVAILABLE')");for($n=1;$n<=(int)round($ln['qty']);$n++){do{$serial='PFS-'.strtoupper(preg_replace('/[^A-Z0-9]/i','',$p['sku'])).'-'.$batchId.'-'.str_pad((string)$n,5,'0',STR_PAD_LEFT).'-'.strtoupper(bin2hex(random_bytes(1)));$check=db()->prepare('SELECT 1 FROM product_serials WHERE serial_barcode=?');$check->execute([$serial]);}while($check->fetchColumn());$ins->execute([$serial,$ln['product_id'],$batchId,$ln['location']]);}}
  }
  db()->commit();audit('PURCHASE_INWARD','purchase',$purchaseId,['purchase_no'=>$purchaseNo,'items'=>count($lines),'total'=>$total]);publish_event('PURCHASE_INWARD','Purchase posted',$purchaseNo.' · Total ₹'.number_format($total,2),['super_admin'],'purchase',$purchaseId,null);publish_scoped_event('PURCHASE_STOCK_IN','New stock received',$purchaseNo.' · '.count($lines).' line(s) received',['manager','godown'],'purchase',$purchaseId);$success=$purchaseNo.' posted successfully.';
 }catch(Throwable $e){if(db()->inTransaction())db()->rollBack();$labelBatches=[];$err='Could not post purchase: '.user_error_message($e,'A batch/lot number is already used for one of these products. Use a new batch/lot number.');}
}
page_header('Purchase Inward · Multi Item / Batch Creation');if($err)echo '<div class="notice error">'.e($err).'</div>';if($success){echo '<div class="notice success">'.e($success).' <a href="purchases.php">Open Purchase History</a>';if($labelBatches){echo '<br>Print barcode labels: ';foreach($labelBatches as $lb)echo '<a class="btn secondary" target="_blank" href="barcode_labels.php?batch_id='.(int)$lb['id'].'">'.e($lb['label']).'</a> ';}echo '</div>';}
$scanMap=[];foreach($products as $p){$scanMap[strtoupper($p['sku'])]=(int)$p['id'];if($p['product_barcode']!=='')$scanMap[strtoupper($p['product_barcode'])]=(int)$p['id'];} ?>
<div class="notice"><b>Super Admin only:</b> purchase rates are never exposed to Cashier/Godown. Serialized garments automatically receive one unique barcode per piece.</div>
<form class="panel" id="purchaseScanForm" autocomplete="off"><label for="purchaseScan">Scan product barcode / SKU to add a line</label><input id="purchaseScan" data-scanner placeholder="Scan or type barcode / SKU and press Enter"><div class="muted" id="purchaseScanMsg"></div></form>
<form method="post" class="panel" id="purchaseForm"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="form_once" value="<?=e(form_once_token('purchase_new'))?>"><div class="row3"><div><label>Supplier / Party</label><select name="supplier_id" required><option value="">-- Select --</option><?php foreach($suppliers as $s):?><option value="<?=$s['id']?>"><?=e($s['party_code'].' · '.$s['party_name'])?></option><?php endforeach;?></select></div><div><label>Supplier Invoice No.</label><input name="invoice_no"></div><div><label>Invoice Date</label><input type="date" name="invoice_date" value="<?=date('Y-m-d')?>" required></div></div><br>
<table id="lines"><tr><th>Product</th><th>Batch/Lot</th><th>Location</th><th>Qty</th><th>Purchase Rate</th><th>Secret Cost Code</th><th></th></tr><tbody></tbody></table><br><div class="actions"><button type="button" class="btn secondary" onclick="addLine()">+ Add Item</button><button class="btn">POST PURCHASE & CREATE STOCK</button></div></form>
<template id="lineTemplate"><tr><td><select name="product_id[]" required><option value="">--</option><?php foreach($products as $p):?><option value="<?=$p['id']?>"><?=e($p['sku'].' · '.$p['product_name'].' · '.$p['color'].' '.$p['size'].((int)$p['serial_tracking']?' · SERIAL':' · BATCH'))?></option><?php endforeach;?></select></td><td><input name="batch_no[]" required placeholder="LOT-001"></td><td><select name="location_id[]" required><?php foreach($locations as $l):?><option value="<?=$l['id']?>"><?=e($l['code'].' · '.$l['name'])?></option><?php endforeach;?></select></td><td><input type="number" step="0.001" min="0.001" name="quantity[]" value="1" required></td><td><input type="number" step="0.01" min="0" name="cost_price[]" required></td><td><input name="cost_code[]" maxlength="80" placeholder="Optional / auto"></td><td><button type="button" class="btn danger" onclick="this.closest('tr').remove()">×</button></td></tr></template>
<script>function addLine(){document.querySelector('#lines tbody').appendChild(document.getElementById('lineTemplate').content.cloneNode(true));}addLine();
(function(){
  const map=<?=json_encode($scanMap,JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT)?>;
  const form=document.getElementById('purchaseScanForm'),input=document.getElementById('purchaseScan'),msg=document.getElementById('purchaseScanMsg');
  form.addEventListener('submit',function(ev){
    ev.preventDefault();
    const code=input.value.trim().toUpperCase();input.value='';
    if(!code)return;
    const pid=map[code];
    if(!pid){msg.textContent='Not found: '+code+'. Create the product first in Product Master.';return;}
    const selects=[...document.querySelectorAll('#lines select[name="product_id[]"]')];
    let sel=selects.find(s=>s.value===String(pid));
    if(sel){const q=sel.closest('tr').querySelector('input[name="quantity[]"]');q.value=(parseFloat(q.value)||0)+1;}
    else{sel=selects.find(s=>s.value==='');if(!sel){addLine();const all=document.querySelectorAll('#lines select[name="product_id[]"]');sel=all[all.length-1];}sel.value=String(pid);}
    msg.textContent='Added: '+sel.options[sel.selectedIndex].text;
    input.focus();
  });
  document.getElementById('purchaseForm').addEventListener('submit',function(){const b=this.querySelector('button:not([type=button])');if(b){b.disabled=true;b.textContent='Posting…';}});
})();</script>
